import sys

s = sys.stdin.read().split()[0]
# state per employee: 0 = seated, 1 = in meeting, 2 = gone
emps = []
best = 0
for c in s:
    if c == 'C':
        emps.append(0)
    elif c == 'R':
        for i in range(len(emps)):
            if emps[i] == 0:
                emps[i] = 1
                break
    elif c == 'U':
        for i in range(len(emps)):
            if emps[i] == 1:
                emps[i] = 0
                break
    else:
        for i in range(len(emps)):
            if emps[i] == 0:
                emps[i] = 2
                break
    best = max(best, sum(1 for e in emps if e == 0))
print(best)

