def gen(rng):
    def valid(n, wc, wr, wu, wl):
        seated = away = 0
        out = []
        for _ in range(n):
            moves = ['C']
            weights = [wc]
            if seated > 0:
                moves += ['R', 'L']
                weights += [wr, wl]
            if away > 0:
                moves.append('U')
                weights.append(wu)
            m = rng.choices(moves, weights)[0]
            if m == 'C':
                seated += 1
            elif m == 'R':
                seated -= 1
                away += 1
            elif m == 'U':
                away -= 1
                seated += 1
            else:
                seated -= 1
            out.append(m)
        return ''.join(out)
    tests = ['C', 'CL', 'CCCRCCUL', 'CCRUL', 'CLCL', 'CRU', 'CCCCC', 'CRCRCRUUU', 'CCCRRRUUUL']
    for _ in range(40):
        tests.append(valid(rng.randint(1, 30), rng.randint(1, 5), rng.randint(1, 5), rng.randint(1, 5), rng.randint(1, 5)))
    N = 200000
    tests.append('C' * N)
    tests.append(valid(N, 5, 3, 3, 2))
    tests.append(valid(N, 3, 3, 3, 3))
    tests.append('CR' * (N // 2 - 1) + 'U' * 1 + 'C')
    tests.append('C' * (N // 2) + 'R' * (N // 4) + 'U' * (N // 4) + 'L' * (N // 4))
    return tests

